<template>
  <div 
    ref="carouselContainer"
    class="infinite-carousel"
    tabindex="0"
    role="region"
    :aria-label="carouselLabel"
    @keydown.enter="openLightbox(0)"
    @keydown.space.prevent="openLightbox(0)"
  >
    <Splide 
      :options="options" 
      :extensions="extensions"
      :aria-label="carouselLabel"
      @splide:mounted="disableArrowTabbing"
      @splide:updated="disableArrowTabbing"
    >
      <SplideSlide v-for="(image, index) in images" :key="index">
        <div 
          class="carousel-item" 
          @click="openLightbox(index)"
        >
          <img 
            :data-splide-lazy="resolveImageUrl(image.url)" 
            :src="resolveImageUrl(image.url)" 
            :alt="image.alt || 'Carousel image'" 
            loading="lazy" 
            decoding="async"
          >
        </div>
      </SplideSlide>
    </Splide>

    <!-- Lightbox Modal Overlay -->
    <Teleport to="body">
      <Transition name="lightbox-fade">
        <div 
          v-if="selectedIndex !== null && activeImage" 
          class="lightbox-overlay"
          @click="closeLightbox"
          @touchstart.passive="handleTouchStart"
          @touchend.passive="handleTouchEnd"
          role="dialog"
          aria-modal="true"
          :aria-label="activeImage.alt || 'Expanded Image View'"
        >
          <!-- Close Button -->
          <button 
            class="lightbox-close" 
            @click.stop="closeLightbox" 
            aria-label="Close image modal"
            type="button"
          >
            <svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round">
              <line x1="18" y1="6" x2="6" y2="18"></line>
              <line x1="6" y1="6" x2="18" y2="18"></line>
            </svg>
          </button>

          <!-- Previous Button (fixed screen position) -->
          <button 
            class="lightbox-nav lightbox-nav--prev" 
            @click.stop="prevImage" 
            aria-label="Previous image"
            type="button"
          >
            <svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="15 18 9 12 15 6"></polyline>
            </svg>
          </button>

          <div class="lightbox-content">
            <!-- Main Media & Caption -->
            <div class="lightbox-media-wrapper">
              <img 
                :src="resolveImageUrl(activeImage.url)" 
                :alt="activeImage.alt || 'Carousel image'" 
                class="lightbox-image"
                decoding="async"
                @click.stop
              />
              <div v-if="activeImage.alt" class="lightbox-caption" @click.stop>
                <p>{{ activeImage.alt }}</p>
              </div>
            </div>
          </div>

          <!-- Next Button (fixed screen position) -->
          <button 
            class="lightbox-nav lightbox-nav--next" 
            @click.stop="nextImage" 
            aria-label="Next image"
            type="button"
          >
            <svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="9 18 15 12 9 6"></polyline>
            </svg>
          </button>
        </div>
      </Transition>
    </Teleport>
  </div>
</template>

<script>
import { Splide, SplideSlide } from '@splidejs/vue-splide';
import { AutoScroll } from '@splidejs/splide-extension-auto-scroll';
import '@splidejs/vue-splide/css';

export default {
  name: 'InfiniteCarousel',
  components: {
    Splide,
    SplideSlide,
  },
  props: {
    name: {
      type: String,
      default: 'Gallery',
    },
    images: {
      type: Array,
      required: true,
      default: () => [],
    },
    speed: {
      type: Number,
      default: 0.7,
    }
  },
  data() {
    return {
      extensions: {
        AutoScroll,
      },
      selectedIndex: null,
      touchStartX: 0,
      touchStartY: 0,
    };
  },
  computed: {
    carouselLabel() {
      return `${this.name} image carousel`;
    },
    options() {
      return {
        type: 'loop',
        drag: 'free',
        focus: 'center',
        autoWidth: true,
        gap: '2rem',
        arrows: true,
        keyboard: false,
        pagination: false,
        lazyLoad: 'nearby',
        autoScroll: {
          speed: this.speed,
          pauseOnHover: true,
          pauseOnFocus: true,
          rewind: false,
        },
      };
    },
    activeImage() {
      if (this.selectedIndex === null || !this.images || !this.images.length) return null;
      return this.images[this.selectedIndex];
    }
  },
  mounted() {
    window.addEventListener('keydown', this.handleKeyDown);
    this.$nextTick(() => {
      this.disableArrowTabbing();
    });
  },
  beforeUnmount() {
    window.removeEventListener('keydown', this.handleKeyDown);
    if (this.selectedIndex !== null) {
      document.body.style.overflow = '';
    }
  },
  methods: {
    disableArrowTabbing() {
      if (this.$refs.carouselContainer) {
        const arrows = this.$refs.carouselContainer.querySelectorAll('.splide__arrow');
        arrows.forEach((arrow) => {
          arrow.setAttribute('tabindex', '-1');
          arrow.setAttribute('aria-hidden', 'true');
        });
      }
    },
    openLightbox(index) {
      this.selectedIndex = index;
      document.body.style.overflow = 'hidden';
    },
    closeLightbox() {
      this.selectedIndex = null;
      document.body.style.overflow = '';
      this.$nextTick(() => {
        if (this.$refs.carouselContainer) {
          this.$refs.carouselContainer.focus();
        }
      });
    },
    prevImage() {
      if (this.selectedIndex !== null && this.images.length > 0) {
        this.selectedIndex = (this.selectedIndex - 1 + this.images.length) % this.images.length;
      }
    },
    nextImage() {
      if (this.selectedIndex !== null && this.images.length > 0) {
        this.selectedIndex = (this.selectedIndex + 1) % this.images.length;
      }
    },
    handleKeyDown(event) {
      if (this.selectedIndex === null) return;
      if (event.key === 'Escape') {
        this.closeLightbox();
      } else if (event.key === 'ArrowLeft') {
        this.prevImage();
      } else if (event.key === 'ArrowRight') {
        this.nextImage();
      }
    },
    handleTouchStart(event) {
      if (event.touches && event.touches.length === 1) {
        this.touchStartX = event.touches[0].clientX;
        this.touchStartY = event.touches[0].clientY;
      }
    },
    handleTouchEnd(event) {
      if (event.changedTouches && event.changedTouches.length === 1) {
        const deltaX = event.changedTouches[0].clientX - this.touchStartX;
        const deltaY = event.changedTouches[0].clientY - this.touchStartY;
        const minSwipeDistance = 40; // minimum swipe distance in px

        // Verify gesture is primarily horizontal to avoid triggering during vertical adjustments
        if (Math.abs(deltaX) > minSwipeDistance && Math.abs(deltaX) > Math.abs(deltaY)) {
          if (deltaX < 0) {
            this.nextImage(); // Swiped left -> next
          } else {
            this.prevImage(); // Swiped right -> prev
          }
        }
      }
    },
    resolveImageUrl(url) {
      if (!url) return '';
      const trimmed = url.trim();
      if (/^(https?:|\/|data:)/i.test(trimmed)) {
        return trimmed;
      }
      if (trimmed.startsWith('gallery/') || trimmed.startsWith('new_gallery/')) {
        return `/${trimmed}`;
      }
      return `/gallery/${trimmed}`;
    }
  }
};
</script>

