<template>
  <div class="sponsor-tile" :href="data.link">
    <a class="sponsor-link" :href="data.link" target="_blank">
      <img :src="logoSrc" :alt="data.name" class="sponsor-logo" loading="lazy" decoding="async" />
      <p class="sponsor-name" > <b>{{ data.name }}</b></p>
      <p class="sponsor-tier">{{ data.tier }}</p>
    </a>
  </div>
</template>

<script>
export default {
  name: "SponsorTile",
  props: {
    data: {
      type: Object,
      required: true
    }
  },
  computed: {
    logoSrc() {
      if (!this.data.logo) return '';
      const logo = this.data.logo.trim();
      if (/^(https?:|\/|data:)/i.test(logo)) {
        return logo;
      }
      if (logo.startsWith('sponsors/')) {
        return `/${logo}`;
      }
      return `/sponsors/${logo}`;
    }
  }
}
</script>

