<template>
  <div class="leader-tile">
    <a :href="data.linkedin" class="leader-text" target="_blank">
        <div class="leader-headshot">
            <img :src="imageSrc" :alt="data.name" class="leader-image" loading="lazy" decoding="async"/>
        </div>
    <p class="name"><b>{{ data.name }}</b></p>
    <p class="pronouns"><i>({{ data.pronouns }})</i></p>
    <p class="position">{{ data.position }}</p>
    </a>
</div>
</template>

<script>
export default {
    name: "LeaderTile",
    props: {
        data: {
            type: Object,
            required: true
        }
    },
    computed: {
        imageSrc() {
            if (!this.data.image) return '';
            const img = this.data.image.trim();
            if (/^(https?:|\/|data:)/i.test(img)) {
                return img;
            }
            if (img.startsWith('headshots/')) {
                return `/${img}`;
            }
            return `/headshots/${img}`;
        }
    }
}
</script>

